    ap_course: p.id,
    course: p.name,
    exam_year: p.year,
    taken_on: date,
    composite: Math.round(Number(result.composite) * 10) / 10,
    estimated_ap_score: Number(result.estimated),
    score_low: result.range ? Number(result.range[0]) : Number(result.estimated),
