  AP_EXAM_FOLDER,
  AP_EXAM_TYPE,
  apExamFrontmatter,
  apExamTrend,
  buildApExamNote,
  writtenSectionsFromFrontmatter,
  entryFromFrontmatter,
  isApExamNote,
  normalizeDate,
  sortApExamEntries,
