  hw: "homework",
  reading: "homework",
  worksheet: "homework",
  "problem-set": "homework",
  problemset: "homework",
  quiz: "quiz",
  check: "quiz",
  "check-in": "quiz",
  test: "test",
  midterm: "test",
  "mid-term": "test",
  exam: "exam",
  final: "exam",
  project: "project",
  paper: "project",
  essay: "project",
  lab: "project",
