  constructor(app, plugin) {
    super(app);
    this.app = app;
    this.plugin = plugin;
    this.config = normalizeAutoAnki(plugin.settings.autoAnki, plugin.settings.cards.defaultDeck);
    this.context = null;
    this.source = "note";
    this.deck = this.config.deck || plugin.settings.cards.defaultDeck || "General";
    this.busy = false;
    this.error = "";
    this.result = null;
  }

