    el.createEl("p", {
      cls: "qt-hint",
      text: `${r.cards} card${r.cards === 1 ? "" : "s"} from ${r.sourceKind === "selection" ? "the selection" : "the note"} · ${added} added to Anki${updated ? `, ${updated} updated` : ""}.`,
    });
