const CARD_GRADES = ["again", "hard", "good", "easy"];
const CARD_ITEM_TYPES = ["card", "flashcard", "vocab", "vocabulary"];
const CARD_SCHEDULERS = ["ladder", "sm2", "fsrs"];
const REVEAL_ANIMATIONS = ["instant", "fade", "flip"];

