    if (deck && deck !== "all" && lower(c.deck) !== deck) return false;
    if (course && course !== "all" && lower(c.course) !== course) return false;
    if (!isStudyable(c.fm, today)) return false;
    return opts.order === "all" || isDue(c.fm, today) || !Number(c.fm.attempts);
