    const heading = pageHeading(page, label);
    lines.push(`## ${heading.title}`, "");
    if (str(m.sourceLink).trim()) lines.push(`*Source: ${str(m.sourceLink).trim()} · ${label.toLowerCase()} ${Number(page.n) || ""}*`, "");
