__defs["course-overview"] = function (module, exports, require) {
/*
 * One read-only "what do I need to learn for this course" view. Every section
 * is derived from an existing store; this module never writes.
 */
const { str, localDate } = require("./util");
const courseIdentity = require("./course-identity");
const { listExams } = require("./exams");
const { planProgress } = require("./study-workspace");

function asObject(value) {
  return value && typeof value === "object" && !Array.isArray(value) ? value : {};
}

function openAssignment(assignment) {
  return assignment && assignment.open !== false && assignment.done !== true;
}

function courseOverview(courseId, ctx) {
  const input = asObject(ctx);
  const settings = input.settings || {};
  const today = str(input.today || localDate()).slice(0, 10);
  const info = courseIdentity.courseDetails(settings, courseId);
  const name = info.name || str(courseId);
  const same = (value) => courseIdentity.sameCourse(settings, value, courseId);
  const exams = Array.isArray(input.exams)
    ? input.exams
    : listExams({ settings, events: input.events, assignments: input.assignments, plans: input.plans, today, includePast: true });
  const futureExams = exams.filter((exam) => exam.date >= today && same(exam.course)).sort((a, b) => a.date.localeCompare(b.date));
  const nextExam = futureExams[0] || null;
  const studyPlan = input.studyPlan && (!input.studyPlan.course || same(input.studyPlan.course)) && (!nextExam || input.studyPlan.examDay === nextExam.date) ? input.studyPlan : null;
  const lastPast = exams.filter((exam) => exam.date < today && same(exam.course)).sort((a, b) => b.date.localeCompare(a.date))[0] || null;
  const lectures = (Array.isArray(input.lectures) ? input.lectures : [])
    .filter((lecture) => same(lecture.course) && (!lastPast || !lecture.date || lecture.date > lastPast.date))
    .sort((a, b) => b.date.localeCompare(a.date));
  const readings = (Array.isArray(input.readings) ? input.readings : [])
    .filter((reading) => !reading.course || same(reading.course))
    .map((reading) => ({
      ...reading,
      course: name,
      pagesRemaining: Math.max(0, Number(reading.pagesRemaining ?? reading.remainingPages) || 0),
      behindPages: Math.max(0, Number(reading.behindPages ?? reading.behindBy) || 0),
      dueDate: str(reading.dueDate || reading.due || "").slice(0, 10),
      source: "reading",
    }));
  const assignments = (Array.isArray(input.assignments) ? input.assignments : [])
    .filter((assignment) => same(assignment.course) && openAssignment(assignment))
    .sort((a, b) => str(a.due || "9999-12-31").localeCompare(str(b.due || "9999-12-31")));
  const tasks = (Array.isArray(input.tasks) ? input.tasks : [])
    .filter((task) => same(task.course) && !task.done)
    .sort((a, b) => str(a.due || "9999-12-31").localeCompare(str(b.due || "9999-12-31")));
  const plan = (Array.isArray(input.plans) ? input.plans : []).find((row) => same(row.course)) || null;
  const progress = plan ? planProgress(plan) : { passes: 0, target: 0, percent: 0, complete: false };
  const course = (Array.isArray(input.courses) ? input.courses : []).find((row) => same(row.name || row.course)) || null;
  const grade = course ? { current: course.current ?? null, letter: course.letter || "", weighted: course.weighted ?? null, graded: Number(course.graded) || 0, credits: Number(course.credits) || 0 } : null;

  const sections = [];
  if (nextExam) {
    const topics = Array.isArray(nextExam.topics) ? nextExam.topics : [];
    const readiness = studyPlan
      ? ` · ${studyPlan.daysLeft} day${studyPlan.daysLeft === 1 ? "" : "s"} left · ${studyPlan.readiness === null ? "readiness not set" : `readiness ${studyPlan.readiness}%`}`
      : "";
    const evidence = studyPlan && Array.isArray(studyPlan.readinessEvidence)
      ? studyPlan.readinessEvidence.map((row) => `${row.label}: ${row.value == null ? "—" : row.value}${row.detail ? ` (${row.detail})` : ""}`).join(" · ")
      : "";
    sections.push({
      id: "exam",
      title: "Next exam",
      rows: [{
        id: nextExam.id,
        label: nextExam.title,
        detail: `${nextExam.date}${nextExam.time ? ` · ${nextExam.time}` : ""}${nextExam.weight ? ` · weight ${nextExam.weight}` : ""}${readiness}${topics.length ? ` · topics: ${topics.join(", ")}` : ""}`,
        source: "exam",
        exam: nextExam,
        path: nextExam.assignment && nextExam.assignment.file ? nextExam.assignment.file.path : "",
        evidence,
      }],
    });
  }
  if (!progress.complete && progress.target > 0) {
    sections.push({
      id: "topics",
      title: "Topics",
      rows: [{
        id: "topic-plan",
        label: `${Math.max(0, progress.target - progress.passes)} topic ${progress.target - progress.passes === 1 ? "pass" : "passes"} left`,
        detail: `${progress.passes}/${progress.target} passes complete`,
        source: "plan",
        plan,
      }],
    });
  }
  if (lectures.length) {
    sections.push({
      id: "lectures",
      title: "Lectures",
      rows: lectures.slice(0, 8).map((lecture) => ({
        id: lecture.id,
        label: lecture.title,
        detail: `${lecture.date}${lecture.topicList && lecture.topicList.length ? ` · ${lecture.topicList.join(", ")}` : ""}`,
        source: "lecture",
        notePath: lecture.notePath || "",
        lecture,
      })),
    });
  }
  if (readings.length) {
    sections.push({
      id: "readings",
      title: "Readings",
      rows: readings.map((reading) => ({
        id: reading.id,
        label: reading.title || "Reading",
        detail: `${reading.pagesRemaining} pages left${reading.behindPages ? ` · ${reading.behindPages} behind` : ""}${reading.dueDate ? ` · due ${reading.dueDate}` : ""}`,
        source: "reading",
        reading,
        path: reading.sourcePath || reading.path || "",
      })),
    });
  }
  if (assignments.length) {
    sections.push({
      id: "assignments",
      title: "Assignments",
      rows: assignments.slice(0, 10).map((assignment) => ({
        id: assignment.id,
        label: assignment.title,
        detail: `${assignment.typeLabel || assignment.type || "Assignment"}${assignment.due ? ` · due ${assignment.due}` : ""}`,
        source: "assignment",
        path: assignment.file && assignment.file.path ? assignment.file.path : "",
        assignment,
      })),
    });
  }
  if (tasks.length) {
    sections.push({
      id: "tasks",
      title: "Tasks",
      rows: tasks.slice(0, 10).map((task) => ({
        id: task.id,
        label: task.title,
        detail: task.due ? `due ${task.due}` : "no due date",
        source: "task",
        task,
        path: task.path || "",
      })),
    });
  }
  if (grade && (grade.graded || grade.current !== null)) {
    sections.push({
      id: "grades",
      title: "Grade",
      rows: [{
        id: "grade-summary",
        label: `${grade.letter || "Grade"}${grade.weighted !== null ? ` · ${grade.weighted}%` : ""}`,
        detail: `${grade.graded} graded item${grade.graded === 1 ? "" : "s"}`,
        source: "grade",
        grade,
      }],
    });
  }
  return {
    id: info.id || str(courseId),
    name,
    course: name,
    color: info.color || (course && course.color) || "",
    folder: info.folder || (course && course.folder) || "",
    nextExam,
    studyPlan,
    lectures,
    readings,
    assignments,
    tasks,
    plan,
    progress,
    grade,
    sections,
  };
}

module.exports = { courseOverview };
};

/* ---- src/course-overview-modal.js ---- */
__defs["course-overview-modal"] = function (module, exports, require) {
const { Modal, Notice } = require("obsidian");
const { str } = require("./util");

class CourseOverviewModal extends Modal {
  constructor(app, plugin, courseId) {
    super(app);
    this.plugin = plugin;
    this.courseId = courseId;
  }

  onOpen() {
    const data = this.plugin.courseOverviewData(this.courseId);
    const { contentEl } = this;
    contentEl.empty();
    if (!data) {
      contentEl.createEl("h3", { text: "Course overview" });
      contentEl.createDiv({ cls: "qt-hint", text: "That course is no longer in the registry or dashboard." });
      return;
    }
    const head = contentEl.createDiv({ cls: "qt-workspace-head" });
    const title = head.createEl("h3");
    const dot = title.createSpan({ cls: "qt-workspace-subject-dot" });
    dot.style.background = data.color || "#7c9cf5";
    title.createSpan({ text: data.name });
    head.createSpan({ cls: "qt-workspace-grade", text: data.grade && data.grade.letter ? `${data.grade.letter}${data.grade.weighted !== null ? ` · ${data.grade.weighted}%` : ""}` : "No grades" });
    contentEl.createDiv({ cls: "qt-hint", text: "Everything here is derived from your notes and local settings. Open a row to jump to its source." });

    if (!data.sections.length) {
      contentEl.createDiv({ cls: "qt-study-empty", text: "Nothing is scheduled or due for this course yet." });
      return;
    }
    for (const section of data.sections) {
      const card = contentEl.createDiv({ cls: "qt-study-card" });
      card.createEl("h4", { text: section.title });
      const list = card.createDiv({ cls: "qt-study-list" });
      for (const row of section.rows) {
        const item = list.createDiv({ cls: "qt-study-row" });
        const main = item.createDiv({ cls: "qt-study-row-main" });
        main.createDiv({ cls: "qt-study-row-title", text: row.label });
        if (row.detail) main.createDiv({ cls: "qt-study-row-meta", text: row.detail });
        if (row.evidence) main.createDiv({ cls: "qt-study-row-meta", text: row.evidence });
        const canOpen = !!(
          row.widget ||
          row.notePath ||
          row.path ||
          ["plan", "reading", "task", "assignment", "grade"].includes(row.source) ||
          (row.source === "exam" && row.exam && row.exam.calendarEvent)
        );
        if (canOpen) item.createEl("button", { text: "Open" }).addEventListener("click", () => this.openRow(row));
      }
    }
  }

  openRow(row) {
    if (row.notePath) {
      this.plugin.app.workspace.openLinkText(row.notePath, "", false);
      return;
    }
    if (row.path) {
      this.plugin.app.workspace.openLinkText(row.path, "", false);
      return;
    }
    if (row.source === "exam" && row.exam && row.exam.calendarEvent) {
      this.plugin.openClassNote(row.exam.calendarEvent, row.exam.date);
      return;
    }
    if (row.source === "plan") {
      this.plugin.activateStudyWorkspace("planner");
      return;
    }
    if (row.source === "reading") {
      this.plugin.activateStudyWorkspace("readingLibrary");
      return;
    }
    if (row.source === "task") {
      this.plugin.activateStudyWorkspace("tasks");
      return;
    }
    if (row.source === "assignment" || row.source === "grade") {
      this.plugin.activateAssignments();
    }
  }

  onClose() {
    this.contentEl.empty();
  }
}

module.exports = { CourseOverviewModal };
};

/* ---- src/course-templates.js ---- */
__defs["course-templates"] = function (module, exports, require) {
/*
 * Course note templates. Course Command Center's remaining local idea is
 * note-type/template mapping: choose a note type (lecture, unit, review,
 * assignment, syllabus) and get a consistent course note. Everything is local
 * and the templates are editable text in settings. No Canvas client, OAuth
 * flow or network request is involved.
 */
const { localDate, str } = require("./util");

const MAX_TEMPLATES = 20;
const MAX_BODY = 20000;
const DEFAULT_FOLDER = "Courses";
const NOTE_TYPES = ["lecture", "unit", "review", "assignment", "syllabus"];

const DEFAULT_TEMPLATES = [
  {
    id: "lecture",
    name: "Lecture notes",
    type: "lecture",
    body: "## Overview\n\n## Key concepts\n\n## Worked examples\n\n## Questions to follow up\n",
  },
  {
    id: "unit",
    name: "Unit plan",
    type: "unit",
    body: "## Learning objectives\n\n## Topics\n\n## Readings\n\n## Practice\n",
  },
  {
    id: "review",
    name: "Exam review",
    type: "review",
    body: "## What the exam covers\n\n## Weak spots\n\n## Practice plan\n\n## Formula and definition sheet\n",
  },
  {
    id: "assignment",
    name: "Assignment brief",
    type: "assignment",
    body: "## Task\n\n## Requirements\n\n## Sources\n\n## Checklist\n",
  },
  {
    id: "syllabus",
    name: "Course syllabus",
    type: "syllabus",
    body: "## Course description\n\n## Grading breakdown\n\n## Schedule\n\n## Policies\n",
  },
];

function slug(value, fallback) {
  const clean = str(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40);
  return clean || fallback;
}

function normalizeTemplate(value, index) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const type = NOTE_TYPES.includes(str(source.type).toLowerCase()) ? str(source.type).toLowerCase() : "lecture";
  const name = str(source.name).replace(/\s+/g, " ").trim().slice(0, 120) || `${type[0].toUpperCase()}${type.slice(1)} notes`;
  const body = str(source.body).slice(0, MAX_BODY) || DEFAULT_TEMPLATES.find((entry) => entry.type === type).body;
  return { id: slug(source.id || name, `template-${index + 1}`), name, type, body };
}

function normalizeCourseTemplates(value) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const folder = str(source.folder).trim().replace(/^\/+|\/+$/g, "");
  const raw = Array.isArray(source.templates) ? source.templates : DEFAULT_TEMPLATES;
  const templates = [];
  const seen = new Set();
  for (const entry of raw) {
    const template = normalizeTemplate(entry, templates.length);
    if (seen.has(template.id)) continue;
    seen.add(template.id);
    templates.push(template);
    if (templates.length >= MAX_TEMPLATES) break;
  }
  return {
    enabled: !(value === false || source.enabled === false),
    folder: folder && !/\.\./.test(folder) ? folder.slice(0, 160) : DEFAULT_FOLDER,
    templates: templates.length ? templates : DEFAULT_TEMPLATES.map((entry, index) => normalizeTemplate(entry, index)),
  };
}

function templateVariables(input) {
  const source = input && typeof input === "object" ? input : {};
  return {
    course: str(source.course).trim().slice(0, 120),
    title: str(source.title).trim().slice(0, 160),
    date: /^\d{4}-\d{2}-\d{2}$/.test(str(source.date)) ? str(source.date) : localDate(),
    type: str(source.type).trim().toLowerCase() || "lecture",
  };
}

function fillTemplate(body, variables) {
  const vars = templateVariables(variables);
  return str(body).replace(/\{\{\s*(course|title|date|type)\s*\}\}/gi, (_match, key) => vars[key.toLowerCase()] || "");
}

function findTemplate(settings, typeOrId) {
  const wanted = str(typeOrId).trim().toLowerCase();
  return (
    settings.templates.find((template) => template.id === wanted) ||
    settings.templates.find((template) => template.type === wanted) ||
    settings.templates[0]
  );
}

function safeFileName(value) {
  return (
    str(value)
      .replace(/[\\/:*?"<>|#^[\]]+/g, "-")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 90) || "Course note"
  );
}

/**
 * Render one course note. `template` may be an id or a note type; an unknown
 * value falls back to the first template so a note is still produced.
 */
function renderCourseNote(input, settingsValue) {
  const settings = normalizeCourseTemplates(settingsValue);
  const vars = templateVariables(input);
  const template = findTemplate(settings, input && (input.template || input.type));
  const title = vars.title || `${vars.course || "Course"} ${template.name}`;
  const fileName = safeFileName(title);
  const lines = [
    "---",
    "type: course-note",
  ];
  if (vars.course) lines.push(`course: ${JSON.stringify(vars.course)}`);
  lines.push(`course_note_type: ${template.type}`, `created: ${vars.date}`, "---", "", `# ${title}`, "");
  if (vars.course) lines.push(`**Course:** ${vars.course}`, "");
  lines.push(fillTemplate(template.body, { ...vars, title }).trim(), "");
  return {
    title,
    fileName,
    type: template.type,
    templateId: template.id,
    folder: settings.folder,
    path: `${settings.folder}/${fileName}.md`,
    markdown: `${lines.join("\n").trim()}\n`,
  };
}

function templateChoices(settingsValue) {
  return normalizeCourseTemplates(settingsValue).templates.map((template) => ({ value: template.id, label: `${template.name} (${template.type})` }));
}

class CourseTemplateModal {
  constructor(app, plugin) {
    this.app = app;
    this.plugin = plugin;
    this.error = "";
    this.busy = false;
    const settings = normalizeCourseTemplates(plugin && plugin.settings && plugin.settings.courseTemplates);
    this.values = { course: "", title: "", date: localDate(), template: settings.templates[0].id };
    const { Modal } = require("obsidian");
    this.modal = new Modal(app);
    this.modal.onOpen = () => this.draw();
    this.modal.onClose = () => this.modal.contentEl.empty();
  }

  open() {
    this.modal.open();
  }

  field(parent, label, type, placeholder, key) {
    const wrap = parent.createDiv({ cls: "qt-field" });
    wrap.createEl("label", { text: label });
    const input = wrap.createEl("input", { cls: "qt-input" });
    input.type = type || "text";
    if (placeholder) input.placeholder = placeholder;
    input.value = this.values[key] || "";
    input.addEventListener("input", () => (this.values[key] = input.value));
    return input;
  }

  draw() {
    const el = this.modal.contentEl;
    el.empty();
    el.createEl("h3", { text: "Create a course note" });
    el.createDiv({ cls: "qt-hint", text: "Choose a note type and fill the fields. The template body is editable in Settings, Global, Modules." });
    this.field(el, "Course", "text", "Biology", "course");
    this.field(el, "Title", "text", "Unit 3 — Cell respiration", "title");
    this.field(el, "Date", "date", "", "date");
    const wrap = el.createDiv({ cls: "qt-field" });
    wrap.createEl("label", { text: "Note type" });
    const select = wrap.createEl("select", { cls: "dropdown" });
    for (const choice of templateChoices(this.plugin.settings.courseTemplates)) {
      const option = select.createEl("option", { text: choice.label, value: choice.value });
      if (choice.value === this.values.template) option.selected = true;
    }
    select.addEventListener("change", () => (this.values.template = select.value));
    if (this.error) el.createDiv({ cls: "qt-error", text: this.error });
    const row = el.createDiv({ cls: "qt-row" });
    const create = row.createEl("button", { text: this.busy ? "Creating…" : "Create note", cls: "mod-cta" });
    create.disabled = this.busy;
    create.addEventListener("click", () => this.create());
    row.createEl("button", { text: "Cancel" }).addEventListener("click", () => this.modal.close());
  }

  async create() {
    if (this.busy) return;
    this.busy = true;
    this.error = "";
    this.draw();
    try {
      const result = await this.plugin.createCourseNote(this.values);
      const { Notice } = require("obsidian");
      new Notice(`Course note created: ${result.path}`, 5000);
      this.modal.close();
    } catch (e) {
      this.busy = false;
      this.error = str(e && e.message ? e.message : e) || "Could not create the course note.";
      this.draw();
    }
  }
}

module.exports = {
  DEFAULT_FOLDER,
  DEFAULT_TEMPLATES,
  MAX_TEMPLATES,
  NOTE_TYPES,
  CourseTemplateModal,
  fillTemplate,
  findTemplate,
  normalizeCourseTemplates,
  renderCourseNote,
  safeFileName,
  templateChoices,
  templateVariables,
};
};

/* ---- src/daily-quiz.js ---- */
__defs["daily-quiz"] = function (module, exports, require) {
/*
 * The daily quiz is a small, deterministic set of MCQ notes for one calendar
 * day. It deliberately reuses the normal practice queue and scheduler; this
 * module only chooses the set and tracks the separate daily streak.
 */
const { isDue } = require("./filters");
const { isStudyable } = require("./study-status");
const { addDays, fmtDate, str } = require("./util");

const MAX_DAILY_FREEZES = 3;
const DEFAULT_DAILY_QUIZ = {
  enabled: false,
  count: 5,
  folders: [],
  freezeEnabled: false, // opt-in: a missed day can spend an earned freeze
  freezeEvery: 5, // completed daily quizzes per earned freeze
  freezes: 0,
  completions: 0,
  lastDate: "",
  paths: [],
  streak: 0,
  best: 0,
  lastCompleted: "",
};

function dayKey(value) {
  if (value instanceof Date) return isNaN(value.getTime()) ? "" : fmtDate(value);
  const s = str(value).trim().slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : "";
}

function parseDay(value) {
  const key = dayKey(value);
  if (!key) return null;
  const [year, month, day] = key.split("-").map(Number);
  const date = new Date(year, month - 1, day);
  return isNaN(date.getTime()) ? null : date;
}

function previousDay(value) {
  const date = parseDay(value);
  return date ? fmtDate(addDays(date, -1)) : "";
}

function nonNegative(value) {
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : 0;
}

/** A textarea or an array both become a clean list of folder paths. */
function folderList(value) {
  const list = Array.isArray(value) ? value : str(value).split(/[\n,]+/);
  const out = [];
  for (const item of list) {
    const path = str(item).trim().replace(/^\/+|\/+$/g, "");
    if (path && !out.includes(path)) out.push(path);
  }
  return out;
}

function foldersText(value) {
  return folderList(value).join("\n");
}

function normalizeDailyQuiz(value) {
  const src = value && typeof value === "object" ? value : {};
  const count = Number(src.count);
  const freezeEvery = Number(src.freezeEvery);
  return {
    enabled: src.enabled === true,
    count: Number.isFinite(count) ? Math.min(50, Math.max(1, Math.round(count))) : DEFAULT_DAILY_QUIZ.count,
    folders: folderList(src.folders),
    freezeEnabled: src.freezeEnabled === true,
    freezeEvery: Number.isFinite(freezeEvery) && freezeEvery >= 2 ? Math.min(50, Math.round(freezeEvery)) : DEFAULT_DAILY_QUIZ.freezeEvery,
    freezes: Math.min(MAX_DAILY_FREEZES, nonNegative(src.freezes)),
    completions: nonNegative(src.completions),
    lastDate: dayKey(src.lastDate),
    paths: Array.isArray(src.paths) ? src.paths.filter((p) => typeof p === "string" && p) : [],
    streak: nonNegative(src.streak),
    best: nonNegative(src.best),
    lastCompleted: dayKey(src.lastCompleted),
  };
}

function pathInFolders(path, folders) {
  const list = folderList(folders);
  if (!list.length) return true;
  const clean = str(path).replace(/^\/+/, "");
  return list.some((folder) => clean === folder || clean.startsWith(folder + "/"));
}

function hashSeed(text) {
  let h = 2166136261;
  const s = str(text);
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function randomFrom(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffle(items, seed) {
  const out = items.slice();
  const rnd = randomFrom(seed);
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    const tmp = out[i];
    out[i] = out[j];
    out[j] = tmp;
  }
  return out;
}

/**
 * Choose today's questions. Due questions come first, then unseen ones, then
 * the rest; each group is shuffled with a date seed so reopening the quiz on
 * the same day gives the same set.
 */
function buildDailyQuiz(questions, options) {
  const opts = options || {};
  const today = dayKey(opts.today) || fmtDate(new Date());
  const cfg = normalizeDailyQuiz({ count: opts.count, folders: opts.folders });
  const eligible = (questions || []).filter(
    (q) => q && q.file && pathInFolders(q.file.path, cfg.folders) && isStudyable(q.fm, today)
  );
  const groups = [[], [], []];
  for (const q of eligible) {
    const rank = isDue(q.fm, today) ? 0 : !Number(q.fm && q.fm.attempts) ? 1 : 2;
    groups[rank].push(q);
  }
  const seed = hashSeed(`${today}|${cfg.folders.join("|")}|${cfg.count}`);
  const ordered = [];
  groups.forEach((group, i) => ordered.push(...shuffle(group, seed + i * 7919)));
  return ordered.slice(0, Math.min(cfg.count, ordered.length));
}

/**
 * Use the cached set for today when every saved path still resolves to an
 * eligible note. A renamed, deleted, hidden or moved-away note regenerates the
 * set instead of silently shortening it.
 */
function pickDailyQuiz(questions, state, today) {
  const cfg = normalizeDailyQuiz(state);
  const day = dayKey(today) || fmtDate(new Date());
  if (cfg.lastDate === day && cfg.paths.length) {
    const byPath = new Map((questions || []).filter((q) => q && q.file).map((q) => [q.file.path, q]));
    const cached = [];
    let valid = true;
    for (const path of cfg.paths) {
      const q = byPath.get(path);
      if (!q || !isStudyable(q.fm, day) || !pathInFolders(q.file.path, cfg.folders)) {
        valid = false;
        break;
      }
      cached.push(q);
    }
    if (valid && cached.length) return { state: cfg, questions: cached };
  }
  const questionsForDay = buildDailyQuiz(questions, { today: day, count: cfg.count, folders: cfg.folders });
  return {
    state: { ...cfg, lastDate: day, paths: questionsForDay.map((q) => q.file.path) },
    questions: questionsForDay,
  };
}

function dailyDone(state, today) {
  const cfg = normalizeDailyQuiz(state);
  return !!cfg.lastCompleted && cfg.lastCompleted === (dayKey(today) || fmtDate(new Date()));
}

/** Calendar days strictly between the last completion and today. */
function missedDayKeys(state, today) {
  const cfg = normalizeDailyQuiz(state);
  const day = dayKey(today) || fmtDate(new Date());
  const start = parseDay(cfg.lastCompleted);
  const end = parseDay(day);
  const out = [];
  if (!start || !end) return out;
  let cursor = addDays(start, 1);
  while (cursor < end) {
    out.push(fmtDate(cursor));
    cursor = addDays(cursor, 1);
  }
  return out;
}

/** What the freeze ledger looks like today, without spending anything. */
function dailyFreezeStatus(state, today) {
  const cfg = normalizeDailyQuiz(state);
  const missed = missedDayKeys(cfg, today);
  return {
    enabled: cfg.freezeEnabled,
    freezes: cfg.freezes,
    completions: cfg.completions,
    every: cfg.freezeEvery,
    missedDays: missed.length,
    canProtect: cfg.freezeEnabled && missed.length > 0 && cfg.freezes >= missed.length,
    nextEarnIn: cfg.freezeEvery - (cfg.completions % cfg.freezeEvery),
  };
}

function dailyStreak(state, today) {
  const cfg = normalizeDailyQuiz(state);
  const day = dayKey(today) || fmtDate(new Date());
  if (!cfg.lastCompleted) return 0;
  if (cfg.lastCompleted === day || cfg.lastCompleted === previousDay(day)) return cfg.streak;
  if (cfg.freezeEnabled) {
    const missed = missedDayKeys(cfg, day);
    if (missed.length && cfg.freezes >= missed.length) return cfg.streak;
  }
  return 0;
}

/** Completing the quiz twice in one day never increments the streak twice. */
function completeDailyQuiz(state, today) {
  const cfg = normalizeDailyQuiz(state);
  const day = dayKey(today) || fmtDate(new Date());
  if (cfg.lastCompleted === day) return cfg;
  const missed = missedDayKeys(cfg, day);
  let freezes = cfg.freezes;
  let streak = 1;
  if (cfg.lastCompleted === previousDay(day)) {
    streak = cfg.streak + 1;
  } else if (cfg.freezeEnabled && cfg.lastCompleted && missed.length && freezes >= missed.length) {
    // Spend exactly the missed days the earned freezes cover.
    freezes -= missed.length;
    streak = cfg.streak + 1;
  }
  const completions = cfg.completions + 1;
  if (cfg.freezeEnabled && completions % cfg.freezeEvery === 0) freezes = Math.min(MAX_DAILY_FREEZES, freezes + 1);
  return { ...cfg, freezes, completions, lastCompleted: day, streak, best: Math.max(cfg.best, streak) };
}

module.exports = {
  DEFAULT_DAILY_QUIZ,
  MAX_DAILY_FREEZES,
  buildDailyQuiz,
  completeDailyQuiz,
  dailyDone,
  dailyFreezeStatus,
  dailyStreak,
  dayKey,
  folderList,
  foldersText,
  missedDayKeys,
  normalizeDailyQuiz,
  pathInFolders,
  pickDailyQuiz,
};
};

