  canvas.height = height;
  const ctx = canvas.getContext ? canvas.getContext("2d") : null;
  if (!ctx) {
    if (this.threeDErrorEl) this.threeDErrorEl.setText("This device did not provide a 2D canvas.");
    return null;
  }
