  const list = (Array.isArray(lectures) ? lectures : [])
    .map(normalizeLectureRow)
    .filter(Boolean)
    .slice(0, MAX_LECTURES)
    .sort((a, b) => a.date.localeCompare(b.date) || a.title.localeCompare(b.title));
