  const cropWidth = Math.max(1, Math.round(c.w * sourceWidth));
  const cropHeight = Math.max(1, Math.round(c.h * sourceHeight));
  const x = Math.min(sourceWidth - cropWidth, Math.max(0, Math.round(c.x * sourceWidth)));
