  const y0 = Math.min(...list.map((area) => Number(area.y)));
  const x1 = Math.max(...list.map((area) => Number(area.x) + Number(area.width)));
  const y1 = Math.max(...list.map((area) => Number(area.y) + Number(area.height)));
