    correct: finalScore >= (Number(q.pass) || DEFAULT_PASS),
    score: finalScore,
    mode: "text",
    type: "text",
    weight: Number(q.weight) || 1,
    key: str(q.answer),
    selected: str(selected),
    explanation: str(q.explanation),
    band: bandForScore(finalScore, q.pass, q.imprecise),
