const { str } = require("./util");
const { formatChoiceSet, normalizeTrueFalse, parseChoiceSet } = require("./answer-types");
const { retrievePassages } = require("./context-retrieval");

const QUIZ_LANGUAGES = [
  "English",
  "Spanish",
  "French",
  "German",
  "Italian",
  "Portuguese",
  "Dutch",
  "Polish",
  "Turkish",
  "Russian",
  "Ukrainian",
  "Arabic",
  "Hebrew",
  "Hindi",
  "Bengali",
  "Chinese (Simplified)",
  "Chinese (Traditional)",
  "Japanese",
  "Korean",
  "Vietnamese",
  "Indonesian",
  "Thai",
];

