  MAX_SOURCE_CHARS,
  MAX_SOURCE_NOTES,
  QUIZ_LANGUAGES,
  QUIZ_TYPES,
  QUIZ_TYPE_IDS,
  buildQuizGeneratorPrompt,
  collectGeneratorSources,
  folderMatches,
