      note,
      file: note.file,
      path,
      title: str(note.fm && note.fm.title) || str(note.file.basename) || path.replace(/^.*\//, "").replace(/\.md$/i, ""),
      onboarded,
      interval: state.interval,
      easeFactor: state.easeFactor,
      lastReviewed: state.lastReviewed,
